var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var names=new[]{"LevelUp_Panel","LevelUp_Manager","XP_Bar_Slider","GameHUD","Pickup_Pool_Manager","EnemySpawner_Manager"};var lines=new System.Collections.Generic.List<string>();foreach(var n in names){var g=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t=>t.gameObject).FirstOrDefault(x=>x.name==n);if(g==null){lines.Add(n+" NOT FOUND");continue;}lines.Add(n+" active="+g.activeSelf+" "+string.Join(" | ",g.GetComponents<Component>().Where(c=>c!=null).Select(c=>c.GetType().Name+((c is Behaviour b)?" enabled="+b.enabled:""))));}return string.Join("\n",lines);
